<section class="page-hero compact"><div class="container"><span class="eyebrow">Scout Workflow</span><h1>My Destination Requests</h1><p>Track pending requests, administrator feedback, approvals and changes.</p></div></section>
<section class="section container"><div class="section-head"><div><h2>Request List</h2><p class="muted">Approved requests become public destination posts.</p></div><a class="btn btn-primary" href="<?= e(url('scout/request/create')) ?>">Create Request</a></div>
<div class="table-wrap panel-table"><table><thead><tr><th>Destination</th><th>Country</th><th>Category</th><th>Cost</th><th>Status</th><th>Admin Feedback</th><th>Actions</th></tr></thead><tbody>
<?php if(!$requests): ?><tr><td colspan="7" class="empty-cell">No requests submitted yet.</td></tr><?php endif; ?>
<?php foreach($requests as $row): ?><tr><td><strong><?= e($row['title']) ?></strong><small class="block muted"><?= e(date('d M Y',strtotime($row['created_at']))) ?></small></td><td><?= e($row['country']) ?></td><td><?= e($row['category']) ?></td><td><?= e($row['cost_level']) ?></td><td><?= status_badge($row['status']) ?></td><td><?= e($row['admin_feedback'] ?: '-') ?></td><td><div class="table-actions"><?php if(in_array($row['status'],['pending','change_requested','rejected'],true)): ?><a class="btn btn-soft btn-sm" href="<?= e(url('scout/request/edit',['id'=>$row['id']])) ?>">Edit / Resubmit</a><form method="post" action="<?= e(url('scout/request/delete')) ?>" onsubmit="return confirm('Delete this request?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="btn btn-danger btn-sm" type="submit">Delete</button></form><?php else: ?><a class="btn btn-dark btn-sm" href="<?= e(url('explore',['search'=>$row['title']])) ?>">View Published</a><?php endif; ?></div></td></tr><?php endforeach; ?>
</tbody></table></div></section>
